    code: 'export function MessageActions({\n  message,\n  canEdit = true,\n  onReply,\n  onForward,\n  onComplete,\n}: {\n  message: ClientMessage;\n  canEdit?: boolean;\n  /** Called when viewer chooses reply. */\n  onReply?: (message: ClientMessage) => void;\n  /** Called when viewer chooses forward. */\n  onForward?: (message: ClientMessage) => void;\n  onComplete?: () => void;\n}) {\n  const { client, userId } = useChatpackUI();\n  const [pending, setPending] = useState(false);\n  const [editing, setEditing] = useState(false);\n  const [body, setBody] = useState(message.body);\n  const [error, setError] = useState<{ code: string; message: string } | null>(null);\n  async function remove(): Promise<void> {\n    setPending(true);\n    setError(null);\n    const result = await client.messages.delete({ messageId: message.id });\n    setPending(false);\n    if (result.error === null) onComplete?.();\n    else setError(result.error);\n  }\n  async function edit(): Promise<void> {\n    if (body.trim() === "") return;\n    setPending(true);\n    setError(null);\n    const result = await client.messages.edit({ messageId: message.id, body: body.trim() });\n    setPending(false);\n    if (result.error === null) {\n      setEditing(false);\n      onComplete?.();\n    } else setError(result.error);\n  }\n  return (\n    <span className="chatpack-ui-message-actions">\n      {message.deletedAt !== null && (\n        <p className="chatpack-ui-message-actions-deleted">Message deleted</p>\n      )}\n      {editing && (\n        <>\n          <textarea\n            className="chatpack-ui-input"\n            value={body}\n            onChange={(event) => setBody(event.target.value)}\n            aria-label="Edit message"\n            rows={2}\n          />\n          <button\n            type="button"\n            className="chatpack-ui-button chatpack-ui-button-primary"\n            disabled={pending}\n            onClick={() => void edit()}\n          >\n            Save\n          </button>\n          <button\n            type="button"\n            className="chatpack-ui-button chatpack-ui-button-ghost"\n            disabled={pending}\n            onClick={() => setEditing(false)}\n          >\n            Cancel\n          </button>\n        </>\n      )}\n      {!editing && (\n        <>\n          <button\n            type="button"\n            className="chatpack-ui-button chatpack-ui-button-ghost"\n            disabled={pending}\n            onClick={() => onReply?.(message)}\n          >\n            Reply\n          </button>\n          <button\n            type="button"\n            className="chatpack-ui-button chatpack-ui-button-ghost"\n            disabled={pending}\n            onClick={() => onForward?.(message)}\n          >\n            Forward\n          </button>\n          {message.deletedAt === null && canEdit && message.senderId === userId && (\n            <button\n              type="button"\n              className="chatpack-ui-button chatpack-ui-button-ghost"\n              disabled={pending}\n              onClick={() => setEditing(true)}\n            >\n              Edit\n            </button>\n          )}\n          {message.deletedAt === null && message.senderId === userId && (\n            <button\n              type="button"\n              className="chatpack-ui-button chatpack-ui-button-destructive"\n              disabled={pending}\n              onClick={() => void remove()}\n            >\n              Delete\n            </button>\n          )}\n        </>\n      )}\n      {error !== null && <small role="alert">{error.message}</small>}\n    </span>\n  );\n}',
